B.bzS={"\u092a\u094d\u0930\u0925\u092e \u092a\u0930\u0916":0,"\u0926\u094d\u0935\u093f\u0924\u0940\u092f \u092a\u0930\u0916":1,"\u0905\u0930\u094d\u0927\u0935\u093e\u0930\u094d\u0937\u093f\u0915":2,"\u0924\u0943\u0924\u0940\u092f \u092a\u0930\u0916":3,"\u0935\u093e\u0930\u094d\u0937\u093f\u0915":4,"\u092a\u0930\u0916":5,"\u092a\u0930\u0940\u0915\u094d\u0937\u093e \u092a\u0930\u093f\u0923\u093e\u092e":6,"\u0909\u0924\u094d\u0915\u0943\u0937\u094d\u091f":7,"\u092c\u0939\u0941\u0924 \u0905\u091a\u094d\u091b\u093e":8,"\u0905\u091a\u094d\u091b\u093e":9,"\u0938\u0902\u0924\u094b\u0937\u091c\u0928\u0915":10,"\u0938\u0941\u0927\u093e\u0930 \u0906\u0935\u0936\u094d\u092f\u0915":11,"\u0935\u093f\u0936\u0947\u0937 \u0927\u094d\u092f\u093e\u0928 \u0906\u0935\u0936\u094d\u092f\u0915":12,"\u0915\u093e\u0930\u094d\u092f\u093e\u0928\u0941\u092d\u0935":13,"\u0915\u0932\u093e \u0936\u093f\u0915\u094d\u0937\u093e":14,"\u0938\u094d\u0935\u093e\u0938\u094d\u0925\u094d\u092f \u090f\u0935\u0902 \u0936\u093e\u0930\u0940\u0930\u093f\u0915 \u0936\u093f\u0915\u094d\u0937\u093e":15,"\u0905\u0928\u0941\u0936\u093e\u0938\u0928":16,"\u092d\u093e\u0937\u093e":17,"\u0917\u0923\u093f\u0924-\u092a\u0942\u0930\u094d\u0935":18,"\u0936\u093e\u0930\u0940\u0930\u093f\u0915":19,"\u0939\u093f\u0902\u0926\u0940":20,"\u0917\u0923\u093f\u0924":21,"\u092a\u0930\u094d\u092f\u093e\u0935\u0930\u0923":22,"\u0935\u093f\u0915\u093e\u0938":23,[u.mf]:24,"\u0938\u094d\u0935\u091a\u094d\u091b\u0924\u093e \u0914\u0930 \u0905\u091a\u094d\u091b\u0940 \u0906\u0926\u0924\u0947\u0902":25,"\u0938\u0941\u0928\u0915\u0930 \u091b\u094b\u091f\u0947 \u0928\u093f\u0930\u094d\u0926\u0947\u0936 \u0938\u092e\u091d\u0928\u093e":26,"\u0905\u092a\u0928\u0940 \u092c\u093e\u0924 2\u20133 \u0936\u092c\u094d\u0926\u094b\u0902 \u092e\u0947\u0902 \u092c\u094b\u0932\u0928\u093e":27,"\u091a\u093f\u0924\u094d\u0930 \u0926\u0947\u0916\u0915\u0930 \u0928\u093e\u092e \u092c\u0924\u093e\u0928\u093e":28,"\u0915\u0935\u093f\u0924\u093e / \u0917\u0940\u0924 \u0939\u093e\u0935-\u092d\u093e\u0935 \u0938\u0947 \u0917\u093e\u0928\u093e":29,"\u091b\u094b\u091f\u093e-\u092c\u0921\u093c\u093e, \u0932\u0902\u092c\u093e-\u091b\u094b\u091f\u093e \u092a\u0939\u091a\u093e\u0928\u0928\u093e":30,"1\u201310 \u0924\u0915 \u092e\u094c\u0916\u093f\u0915 \u0917\u093f\u0928\u0924\u0940":31,"1\u20135 \u0924\u0915 \u0935\u0938\u094d\u0924\u0941\u090f\u0901 \u0917\u093f\u0928\u0928\u093e":32,"\u092e\u0942\u0932 \u0930\u0902\u0917 \u092a\u0939\u091a\u093e\u0928\u0928\u093e":33,"\u0906\u0915\u093e\u0930 \u092a\u0939\u091a\u093e\u0928\u0928\u093e (\u0917\u094b\u0932, \u091a\u094c\u0915\u094b\u0930, \u0924\u094d\u0930\u093f\u092d\u0941\u091c)":34,"\u0926\u094c\u0921\u093c\u0928\u093e, \u0915\u0942\u0926\u0928\u093e, \u0917\u0947\u0902\u0926 \u092a\u0915\u0921\u093c\u0928\u093e":35,"\u0915\u094d\u0930\u0947\u092f\u0949\u0928 \u092a\u0915\u0921\u093c\u0915\u0930 \u0906\u0921\u093c\u0940-\u0916\u0921\u093c\u0940 \u0930\u0947\u0916\u093e \u092c\u0928\u093e\u0928\u093e":36,"\u0935\u0930\u094d\u0923\u094b\u0902 \u0915\u0940 \u0927\u094d\u0935\u0928\u093f \u092a\u0939\u091a\u093e\u0928\u0928\u093e":37,"\u0938\u094d\u0935\u0930 (\u0905\u2013\u0905\u0903) \u092a\u0939\u091a\u093e\u0928\u0928\u093e":38,"\u0935\u094d\u092f\u0902\u091c\u0928 (\u0915\u2013\u091c\u094d\u091e) \u092a\u0939\u091a\u093e\u0928\u0928\u093e":39,"\u0935\u0930\u094d\u0923 \u0932\u093f\u0916\u0928\u093e":40,"\u091a\u093f\u0924\u094d\u0930 \u0926\u0947\u0916\u0915\u0930 3\u20134 \u0935\u093e\u0915\u094d\u092f \u092c\u094b\u0932\u0928\u093e":41,"\u0915\u0939\u093e\u0928\u0940 \u0938\u0941\u0928\u0915\u0930 \u0938\u0935\u093e\u0932\u094b\u0902 \u0915\u0947 \u091c\u0935\u093e\u092c":42,"1\u201320 \u0924\u0915 \u0917\u093f\u0928\u0924\u0940":43,"\u0938\u0902\u0916\u094d\u092f\u093e 1\u201320 \u092a\u0939\u091a\u093e\u0928\u0928\u093e \u0914\u0930 \u0932\u093f\u0916\u0928\u093e":44,"\u0935\u0938\u094d\u0924\u0941\u0913\u0902 \u0915\u094b \u0938\u0902\u0916\u094d\u092f\u093e \u0938\u0947 \u092e\u093f\u0932\u093e\u0928\u093e (1\u201310)":45,"\u092a\u0939\u0932\u0947-\u092c\u093e\u0926-\u092c\u0940\u091a \u0915\u0940 \u0938\u0902\u0916\u094d\u092f\u093e":46,"\u092a\u0948\u091f\u0930\u094d\u0928 \u092a\u0942\u0930\u093e \u0915\u0930\u0928\u093e":47,"\u0930\u0947\u0916\u093e \u0915\u0947 \u0905\u0902\u0926\u0930 \u0930\u0902\u0917 \u092d\u0930\u0928\u093e":48,"\u092e\u093e\u0924\u094d\u0930\u093e\u090f\u0901 \u092a\u0939\u091a\u093e\u0928\u0928\u093e (\u093e \u093f \u0940 \u0941 \u0942)":49,"2\u20133 \u0905\u0915\u094d\u0937\u0930 \u0915\u0947 \u0936\u092c\u094d\u0926 \u092a\u0922\u093c\u0928\u093e":50,"\u092c\u093f\u0928\u093e \u092e\u093e\u0924\u094d\u0930\u093e \u0915\u0947 \u0936\u092c\u094d\u0926 \u0932\u093f\u0916\u0928\u093e":51,"\u091a\u093f\u0924\u094d\u0930-\u0915\u0925\u093e \u0905\u092a\u0928\u0947 \u0936\u092c\u094d\u0926\u094b\u0902 \u092e\u0947\u0902 \u092c\u094b\u0932\u0928\u093e":52,"\u0915\u0935\u093f\u0924\u093e \u092f\u093e\u0926 \u0915\u0930\u0915\u0947 \u0938\u0941\u0928\u093e\u0928\u093e":53,"1\u201350 \u0924\u0915 \u0917\u093f\u0928\u0924\u0940":54,"\u0938\u0902\u0916\u094d\u092f\u093e 1\u201350 \u0932\u093f\u0916\u0928\u093e":55,"\u0935\u0938\u094d\u0924\u0941\u0913\u0902 \u0938\u0947 \u091c\u094b\u0921\u093c (1\u20139)":56,"\u0915\u092e-\u091c\u093c\u094d\u092f\u093e\u0926\u093e \u0924\u0941\u0932\u0928\u093e (1\u201320)":57,"\u0938\u093f\u0915\u094d\u0915\u0947-\u0928\u094b\u091f \u092a\u0939\u091a\u093e\u0928\u0928\u093e":58,"\u0926\u093f\u0928\u094b\u0902 \u0915\u0947 \u0928\u093e\u092e \u0915\u094d\u0930\u092e \u0938\u0947":59,"\u0936\u0930\u0940\u0930 \u0915\u0947 \u0905\u0902\u0917, \u092b\u0932-\u0938\u092c\u094d\u091c\u093c\u0940, \u091c\u093e\u0928\u0935\u0930":60,"\u092e\u093e\u0924\u094d\u0930\u093e \u0935\u093e\u0932\u0947 \u0938\u0930\u0932 \u0936\u092c\u094d\u0926 \u092a\u0922\u093c\u0928\u093e":61,"4\u20135 \u0936\u092c\u094d\u0926\u094b\u0902 \u0915\u0947 \u0935\u093e\u0915\u094d\u092f \u092a\u0922\u093c\u0928\u093e":62,"\u091b\u094b\u091f\u0947 \u0935\u093e\u0915\u094d\u092f \u092a\u0922\u093c\u0915\u0930 \u0938\u092e\u091d\u0928\u093e":63,"\u0938\u0941\u0928\u0915\u0930 \u0938\u0930\u0932 \u0936\u092c\u094d\u0926 \u0932\u093f\u0916\u0928\u093e (\u0936\u094d\u0930\u0941\u0924\u0932\u0947\u0916)":64,"\u0905\u092a\u0928\u0947 \u092c\u093e\u0930\u0947 \u092e\u0947\u0902 4\u20135 \u0935\u093e\u0915\u094d\u092f \u092c\u094b\u0932\u0928\u093e":65,"\u0938\u0902\u0916\u094d\u092f\u093e 1\u201399 \u092a\u0922\u093c\u0928\u093e-\u0932\u093f\u0916\u0928\u093e":66,"\u0926\u0939\u093e\u0908-\u0907\u0915\u093e\u0908 (\u0938\u094d\u0925\u093e\u0928\u0940\u092f \u092e\u093e\u0928)":67,"\u091c\u094b\u0921\u093c (\u0905\u0902\u0915\u094b\u0902 \u092e\u0947\u0902, 1\u201320 \u0924\u0915)":68,"\u0918\u091f\u093e\u0935 (1\u201320 \u0924\u0915)":69,"\u0938\u0902\u0916\u094d\u092f\u093e\u0913\u0902 \u0915\u093e \u0915\u094d\u0930\u092e, \u092c\u0921\u093c\u093e-\u091b\u094b\u091f\u093e":70,"\u0906\u0915\u0943\u0924\u093f\u092f\u093e\u0901 \u0914\u0930 \u092a\u0948\u091f\u0930\u094d\u0928":71,"\u0932\u0902\u092c\u093e\u0908-\u092d\u093e\u0930 \u0915\u0940 \u0924\u0941\u0932\u0928\u093e":72,"\u092a\u0930\u093f\u0935\u093e\u0930, \u0918\u0930 \u0914\u0930 \u0906\u0938\u092a\u093e\u0938":73,[u.es]:74,"\u092a\u0922\u093c\u0915\u0930 \u0938\u0935\u093e\u0932\u094b\u0902 \u0915\u0947 \u091c\u0935\u093e\u092c \u0926\u0947\u0928\u093e":75,"\u0938\u0902\u092f\u0941\u0915\u094d\u0924\u093e\u0915\u094d\u0937\u0930 \u0935\u093e\u0932\u0947 \u0936\u092c\u094d\u0926 \u092a\u0922\u093c\u0928\u093e":76,"2\u20133 \u0935\u093e\u0915\u094d\u092f \u0916\u0941\u0926 \u0932\u093f\u0916\u0928\u093e":77,"\u0936\u094d\u0930\u0941\u0924\u0932\u0947\u0916":78,"\u0938\u0902\u0916\u094d\u092f\u093e 1\u2013999 \u092a\u0922\u093c\u0928\u093e-\u0932\u093f\u0916\u0928\u093e":79,"\u0939\u093e\u0938\u093f\u0932 \u0935\u093e\u0932\u093e \u091c\u094b\u0921\u093c (2 \u0905\u0902\u0915)":80,"\u0909\u0927\u093e\u0930 \u0935\u093e\u0932\u093e \u0918\u091f\u093e\u0935 (2 \u0905\u0902\u0915)":81,"\u0917\u0941\u0923\u093e \u0915\u0940 \u0938\u092e\u091d (\u092c\u093e\u0930-\u092c\u093e\u0930 \u091c\u094b\u0921\u093c)":82,"\u092a\u0939\u093e\u0921\u093c\u0947 2\u20135":83,"\u0918\u0921\u093c\u0940 \u092e\u0947\u0902 \u0938\u092e\u092f (\u0918\u0902\u091f\u093e)":84,"\u0930\u0941\u092a\u092f\u0947-\u092a\u0948\u0938\u0947 \u0915\u093e \u091c\u094b\u0921\u093c":85,"\u092a\u094c\u0927\u0947, \u091c\u093e\u0928\u0935\u0930, \u092d\u094b\u091c\u0928 \u0914\u0930 \u092a\u093e\u0928\u0940":86,"\u0927\u093e\u0930\u093e-\u092a\u094d\u0930\u0935\u093e\u0939 \u092a\u0922\u093c\u0928\u093e (60 \u0936\u092c\u094d\u0926 \u092a\u094d\u0930\u0924\u093f \u092e\u093f\u0928\u091f)":87,"\u092a\u093e\u0920 \u092a\u0922\u093c\u0915\u0930 \u0938\u092e\u091d\u0928\u093e \u0914\u0930 \u0905\u092a\u0928\u0940 \u0930\u093e\u092f":88,"\u0905\u0928\u0941\u091a\u094d\u091b\u0947\u0926 / \u091b\u094b\u091f\u093e \u092a\u0924\u094d\u0930 \u0932\u093f\u0916\u0928\u093e":89,"\u0935\u094d\u092f\u093e\u0915\u0930\u0923: \u0938\u0902\u091c\u094d\u091e\u093e, \u0938\u0930\u094d\u0935\u0928\u093e\u092e, \u0915\u094d\u0930\u093f\u092f\u093e":90,"\u0938\u0941\u0928\u0940 \u0915\u0939\u093e\u0928\u0940 \u0926\u094b\u092c\u093e\u0930\u093e \u0938\u0941\u0928\u093e\u0928\u093e":91,"\u0938\u0902\u0916\u094d\u092f\u093e 1\u20139999":92,"\u091c\u094b\u0921\u093c-\u0918\u091f\u093e\u0935 (3 \u0905\u0902\u0915)":93,"\u0917\u0941\u0923\u093e (2 \u0905\u0902\u0915 \xd7 1 \u0905\u0902\u0915)":94,"\u092d\u093e\u0917 \u0915\u0940 \u0938\u092e\u091d (\u092c\u0930\u093e\u092c\u0930 \u092c\u093e\u0901\u091f\u0928\u093e)":95,"\u092a\u0939\u093e\u0921\u093c\u0947 2\u201310":96,"\u092d\u093f\u0928\u094d\u0928 (\xbd, \xbc)":97,"\u0938\u092e\u092f \u0914\u0930 \u0915\u0948\u0932\u0947\u0902\u0921\u0930":98,"\u092e\u093e\u092a\u0928 (\u092e\u0940\u091f\u0930, \u0915\u093f\u0932\u094b, \u0932\u0940\u091f\u0930)":99,"\u0924\u093e\u0932\u093f\u0915\u093e / \u091a\u093f\u0924\u094d\u0930 \u0938\u0947 \u0906\u0901\u0915\u0921\u093c\u0947 \u092a\u0922\u093c\u0928\u093e":100,"\u0906\u0938\u092a\u093e\u0938, \u092a\u0930\u093f\u0935\u0939\u0928, \u092a\u093e\u0928\u0940 \u092c\u091a\u093e\u0928\u093e":101,"\u0938\u0940\u0916 \u0932\u093f\u092f\u093e":102,"\u0938\u0940\u0916 \u0930\u0939\u093e \u0939\u0948":103,"\u092e\u0926\u0926 \u091a\u093e\u0939\u093f\u090f":104}
